using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Globalization;
namespace Musikbox {
 public class AudioOptions {public string Format="MP3",Codec="",Filter="",Mode="Konvertieren";public int Bitrate=192,Quality=2,SampleRate=0,Channels=0;public bool Vbr;public double Start,End,Volume=0;}
 public static partial class AudioAdvanced {
  public static readonly Dictionary<string,string> Codecs=new Dictionary<string,string>{{"MP3","libmp3lame"},{"FLAC","flac"},{"WAV","pcm_s16le"},{"M4A","aac"},{"OGG","libvorbis"},{"OPUS","libopus"}};
  public static string EncoderArgs(AudioOptions o){if(!Codecs.ContainsKey(o.Format))throw new ArgumentException("Unbekanntes Format");return "-c:a "+Codecs[o.Format]+(o.Format=="FLAC"?" -compression_level "+Math.Min(12,o.Quality):o.Format=="WAV"?"":o.Vbr&&(o.Format=="MP3"||o.Format=="OGG")?" -q:a "+o.Quality:" -b:a "+o.Bitrate+"k")+(o.SampleRate>0?" -ar "+(o.Format=="OPUS"&&!new[]{8000,12000,16000,24000,48000}.Contains(o.SampleRate)?48000:o.SampleRate):"")+(o.Channels>0?" -ac "+o.Channels:"")+(o.Format=="OPUS"?" -vbr "+(o.Vbr?"on":"off"):"");}
  public static string FfmpegBatch(IList<Song> songs,string parent,string exe,AudioOptions o,Action check,Action<int,int,string> progress){if(songs.Count==0)throw new ArgumentException("Keine Titel geladen");if(o.End>0&&o.End<=o.Start)throw new ArgumentException("Ende muss nach dem Beginn liegen");if(o.Start<0)throw new ArgumentException("Negativer Beginn");string stage=BatchFiles.Stage(parent);var log=new StringBuilder();try{int count=o.Mode=="Zusammenfügen"?1:songs.Count;for(int i=0;i<count;i++){check();progress(i,count,songs[i].Title);string input;
   if(o.Mode=="Zusammenfügen"){var decoded=new List<string>();for(int j=0;j<songs.Count;j++){string temp=Path.Combine(stage,"teil-"+j+".wav"),err;Ffmpeg.Run(exe,"-hide_banner -nostdin -v error -n -i "+Ffmpeg.Quote(Path.GetFullPath(songs[j].Source))+" -map 0:a:0 -vn -ar "+(o.SampleRate>0?o.SampleRate:44100)+" -ac "+(o.Channels>0?o.Channels:2)+" -c:a pcm_s16le "+Ffmpeg.Quote(temp),check,out err);decoded.Add(temp);}string list=Path.Combine(stage,"concat.txt");File.WriteAllLines(list,decoded.Select(f=>"file '"+f.Replace("\\","/").Replace("'","'\\''")+"'"),new UTF8Encoding(false));input="-f concat -safe 0 -i "+Ffmpeg.Quote(list);}
   else input="-i "+Ffmpeg.Quote(Path.GetFullPath(songs[i].Source));
   string target=Path.Combine(stage,(i+1).ToString("D4")+" - "+Rules.SafeName(o.Mode=="Zusammenfügen"?"Zusammengefügt":songs[i].Artist+" - "+songs[i].Title)+"."+o.Format.ToLowerInvariant());string trim=o.Start>0?" -ss "+o.Start.ToString(CultureInfo.InvariantCulture):"";if(o.End>0)trim+=" -t "+(o.End-o.Start).ToString(CultureInfo.InvariantCulture);string filter=o.Filter=="Lautheit -16 LUFS"?"loudnorm=I=-16:TP=-1.5:LRA=11":o.Filter=="Hochpass 80 Hz"?"highpass=f=80":o.Filter=="Tiefpass 16 kHz"?"lowpass=f=16000":"";if(o.Volume!=0)filter+=(filter.Length>0?",":"")+"volume="+o.Volume.ToString(CultureInfo.InvariantCulture)+"dB";string error;log.AppendLine(Ffmpeg.Run(exe,"-hide_banner -nostdin -v error -n "+input+trim+" -map 0:a:0 -vn "+EncoderArgs(o)+(filter.Length>0?" -af "+Ffmpeg.Quote(filter):"")+" "+Ffmpeg.Quote(target),check,out error));log.AppendLine(error);MediaMetadata.Write(target,songs[i],songs[i].Album??"");MediaMetadata.PreserveArtwork(songs[i].Source,target,songs[i]);if(o.Mode=="Zusammenfügen"){foreach(string file in Directory.GetFiles(stage,"teil-*.wav"))File.Delete(file);File.Delete(Path.Combine(stage,"concat.txt"));}}
   progress(count,count,"Fertig");File.WriteAllText(Path.Combine(stage,"Verarbeitung.txt"),log.ToString());return BatchFiles.Commit(stage,"FFmpeg");}catch{BatchFiles.Cleanup(stage);throw;}}
  public static string FreacBatch(IList<Song> songs,string parent,string exe,string ffmpeg,AudioOptions o,Action check,Action<int,int,string> progress){var encoders=new Dictionary<string,string>{{"MP3","lame"},{"FLAC","flac"},{"WAV","sndfile"},{"OGG","vorbis"},{"M4A","fdkaac"},{"OPUS","opus"}};if(songs.Count==0)throw new ArgumentException("Keine Titel geladen");string stage=BatchFiles.Stage(parent);var log=new StringBuilder();try{for(int i=0;i<songs.Count;i++){check();progress(i,songs.Count,songs[i].Title);string source=Path.GetFullPath(songs[i].Source),temp=null,error;
   if(o.SampleRate>0||o.Channels>0||MediaProbe57.Extensions.Contains(Path.GetExtension(source).ToLowerInvariant())){temp=Path.Combine(stage,"quelle.wav");Ffmpeg.Run(ffmpeg,"-hide_banner -nostdin -v error -n -i "+Ffmpeg.Quote(source)+" -map 0:a:0 -vn "+(o.SampleRate>0?" -ar "+(o.Format=="OPUS"&&!new[]{8000,12000,16000,24000,48000}.Contains(o.SampleRate)?48000:o.SampleRate):"")+(o.Channels>0?" -ac "+o.Channels:"")+" "+Ffmpeg.Quote(temp),check,out error);source=temp;}
   int inputChannels=o.Channels;if(inputChannels==0)using(var inputFile=TagLib.File.Create(source))inputChannels=inputFile.Properties.AudioChannels;string target=Path.Combine(stage,(i+1).ToString("D4")+" - "+Rules.SafeName(songs[i].Artist+" - "+songs[i].Title)+"."+o.Format.ToLowerInvariant());string options=o.Format=="MP3"?(o.Vbr?" -m VBR -q "+o.Quality:" -m CBR -b "+o.Bitrate):o.Format=="M4A"?" -b "+Math.Min(256,Math.Max(8,o.Bitrate/Math.Max(1,inputChannels))):o.Format=="OPUS"?" --bitrate "+Math.Min(510,o.Bitrate)+" --comp "+Math.Min(10,o.Quality)+(o.Vbr?" --cvbr":" --hard-cbr"):o.Format=="OGG"?(o.Vbr?" -q "+(o.Quality*10):" -b "+o.Bitrate):o.Format=="FLAC"?" -c "+Math.Min(8,o.Quality):"";
   log.AppendLine(Ffmpeg.Run(exe,"--encoder="+encoders[o.Format]+" -o "+Ffmpeg.Quote(target)+" -- "+options+" "+Ffmpeg.Quote(source),check,out error));log.AppendLine(error);if(!File.Exists(target)||new FileInfo(target).Length==0)throw new IOException("fre:ac hat keine Ausgabedatei erstellt");MediaMetadata.Write(target,songs[i],songs[i].Album??"");MediaMetadata.PreserveArtwork(songs[i].Source,target,songs[i]);if(temp!=null)File.Delete(temp);}
   progress(songs.Count,songs.Count,"Fertig");File.WriteAllText(Path.Combine(stage,"freac-Protokoll.txt"),log.ToString());return BatchFiles.Commit(stage,"freac");}catch{BatchFiles.Cleanup(stage);throw;}}
 }
}
